15	package caddyfile
16	
17	import (
18		"fmt"
19		"slices"
20		"strings"
21	)
22	
23	type adjacency map[string][]string
24	
25	type importGraph struct {
26		nodes map[string]struct{}
27		edges adjacency
28	}
29	
30	func (i *importGraph) addNode(name string) {
31		if i.nodes == nil {
32			i.nodes = make(map[string]struct{})
33		}
34		if _, exists := i.nodes[name]; exists {
35			return
36		}
37		i.nodes[name] = struct{}{}
38	}
39	
40	func (i *importGraph) addNodes(names []string) {
41		for _, name := range names {
42			i.addNode(name)
43		}
44	}
45	
46	func (i *importGraph) removeNode(name string) {
47		delete(i.nodes, name)
48	}
49	
50	func (i *importGraph) removeNodes(names []string) {
51		for _, name := range names {
52			i.removeNode(name)
53		}
54	}
55	
56	func (i *importGraph) addEdge(from, to string) error {
57		if !i.exists(from) || !i.exists(to) {
58			return fmt.Errorf("one of the nodes does not exist")
59		}
60	
61		// A cycle is formed if `to` can already reach `from`; adding the edge
62		// would close the loop. Surface the full chain of files involved so the
63		// caller can diagnose the cycle rather than its depth. The closing
64		// endpoints are also named with the established wording so existing
65		// diagnostics (e.g. snippet cycles reported against "Caddyfile") keep
66		// matching.
67		if cycle := i.findPath(to, from); cycle != nil {
68			chain := strings.Join(append(cycle, to), " -> ")
69			return fmt.Errorf(
70				"import cycle detected: %s; a cycle of imports exists between %s and %s",
71				chain, from, to)
72		}
73	
74		if i.areConnected(from, to) {
75			// if connected, there's nothing to do
76			return nil
77		}
78	
79		if i.nodes == nil {
80			i.nodes = make(map[string]struct{})
81		}
82		if i.edges == nil {
83			i.edges = make(adjacency)
84		}
85	
86		i.edges[from] = append(i.edges[from], to)
87		return nil
88	}
89	
90	func (i *importGraph) addEdges(from string, tos []string) error {
91		for _, to := range tos {
92			err := i.addEdge(from, to)
93			if err != nil {
94				return err
95			}
96		}
97		return nil
98	}
99	
100	func (i *importGraph) areConnected(from, to string) bool {
101		al, ok := i.edges[from]
102		if !ok {
103			return false
104		}
105		return slices.Contains(al, to)
106	}
107	
108	// findPath searches for any path through the graph from start to target,
109	// returning the chain of node names (including both ends). It returns nil
110	// when the two nodes are not connected. Edge traversal order follows edge
111	// insertion order so the reported chain is stable across repeated runs.
112	func (i *importGraph) findPath(start, target string) []string {
113		if start == target {
114			return []string{start}
115		}
116	
117		parent := map[string]string{start: ""}
118		queue := []string{start}
119	
120		for len(queue) > 0 {
121			current := queue[0]
122			queue = queue[1:]
123	
124			for _, next := range i.edges[current] {
125				if _, visited := parent[next]; visited {
126					continue
127				}
128				parent[next] = current
129				if next == target {
130					// reconstruct the chain from target back to start
131					chain := []string{target}
132					for node := target; parent[node] != ""; node = parent[node] {
133						chain = append(chain, parent[node])
134					}
135					slices.Reverse(chain)
136					return chain
137				}
138				queue = append(queue, next)
139			}
140		}
141	
142		return nil
143	}
144	
145	func (i *importGraph) exists(key string) bool {
146		_, exists := i.nodes[key]
147		return exists
148	}
