14	
15	package caddyfile
16	
17	import (
18		"bytes"
19		"fmt"
20		"io"
21		"os"
22		"path/filepath"
23		"slices"
24		"strings"
25	
26		"go.uber.org/zap"
27	
28		"github.com/caddyserver/caddy/v2"
29	)
30	
31	// Parse parses the input just enough to group tokens, in
32	// order, by server block. No further parsing is performed.
33	// Server blocks are returned in the order in which they appear.
34	// Directives that do not appear in validDirectives will cause
35	// an error. If you do not want to check for valid directives,
36	// pass in nil instead.
37	//
38	// Environment variables in {$ENVIRONMENT_VARIABLE} notation
39	// will be replaced before parsing begins.
40	func Parse(filename string, input []byte) ([]ServerBlock, error) {
41		// unfortunately, we must copy the input because parsing must
42		// remain a read-only operation, but we have to expand environment
43		// variables before we parse, which changes the underlying array (#4422)
44		inputCopy := make([]byte, len(input))
45		copy(inputCopy, input)
46	
47		tokens, err := allTokens(filename, inputCopy)
48		if err != nil {
49			return nil, err
50		}
51		p := parser{
52			Dispenser: NewDispenser(tokens),
53			importGraph: importGraph{
54				nodes: make(map[string]struct{}),
55				edges: make(adjacency),
56			},
57		}
58		return p.parseAll()
59	}
60	
61	// allTokens lexes the entire input, but does not parse it.
62	// It returns all the tokens from the input, unstructured
63	// and in order. It may mutate input as it expands env vars.
64	func allTokens(filename string, input []byte) ([]Token, error) {
65		return Tokenize(replaceEnvVars(input), filename)
66	}
67	
68	// replaceEnvVars replaces all occurrences of environment variables.
69	// It mutates the underlying array and returns the updated slice.
70	func replaceEnvVars(input []byte) []byte {
71		var offset int
72		for {
73			begin := bytes.Index(input[offset:], spanOpen)
74			if begin < 0 {
75				break
76			}
77			begin += offset // make beginning relative to input, not offset
78			end := bytes.Index(input[begin+len(spanOpen):], spanClose)
79			if end < 0 {
80				break
81			}
82			end += begin + len(spanOpen) // make end relative to input, not begin
83	
84			// get the name; if there is no name, skip it
85			envString := input[begin+len(spanOpen) : end]
86			if len(envString) == 0 {
87				offset = end + len(spanClose)
88				continue
89			}
90	
91			// split the string into a key and an optional default
92			envParts := strings.SplitN(string(envString), envVarDefaultDelimiter, 2)
93	
94			// do a lookup for the env var, replace with the default if not found
95			envVarValue, found := os.LookupEnv(envParts[0])
96			if !found && len(envParts) == 2 {
97				envVarValue = envParts[1]
98			}
99	
100			// get the value of the environment variable
101			// note that this causes one-level deep chaining
102			envVarBytes := []byte(envVarValue)
103	
104			// splice in the value
105			input = append(input[:begin],
106				append(envVarBytes, input[end+len(spanClose):]...)...)
107	
108			// continue at the end of the replacement
109			offset = begin + len(envVarBytes)
110		}
111		return input
112	}
113	
114	type parser struct {
115		*Dispenser
116		block           ServerBlock // current server block being parsed
117		eof             bool        // if we encounter a valid EOF in a hard place
118		definedSnippets map[string][]Token
119		nesting         int
120		importGraph     importGraph
121		// realPathCache memoizes canonical (symlink-resolved) paths of
122		// lexical file paths; see parser.realPath.
123		realPathCache map[string]string
124		// dirEntriesCache memoizes entry names of a directory for the
125		// duration of a parse; see parser.canonicalCasePath.
126		dirEntriesCache map[string][]string
127	}
128	
129	func (p *parser) parseAll() ([]ServerBlock, error) {
130		var blocks []ServerBlock
131	
132		for p.Next() {
133			err := p.parseOne()
134			if err != nil {
135				return blocks, err
136			}
137			if len(p.block.Keys) > 0 || len(p.block.Segments) > 0 {
138				blocks = append(blocks, p.block)
139			}
140			if p.nesting > 0 {
141				return blocks, p.EOFErr()
142			}
143		}
144	
145		return blocks, nil
146	}
147	
148	func (p *parser) parseOne() error {
149		p.block = ServerBlock{}
150		return p.begin()
151	}
152	
153	func (p *parser) begin() error {
154		if len(p.tokens) == 0 {
155			return nil
156		}
157	
158		err := p.addresses()
159		if err != nil {
160			return err
161		}
162	
163		if p.eof {
164			// this happens if the Caddyfile consists of only
165			// a line of addresses and nothing else
166			return nil
167		}
168	
169		if ok, name := p.isNamedRoute(); ok {
170			// we just need a dummy leading token to ease parsing later
171			nameToken := p.Token()
172			nameToken.Text = name
173	
174			// named routes only have one key, the route name
175			p.block.Keys = []Token{nameToken}
176			p.block.IsNamedRoute = true
177	
178			// get all the tokens from the block, including the braces
179			tokens, err := p.blockTokens(true)
180			if err != nil {
181				return err
182			}
183			tokens = append([]Token{nameToken}, tokens...)
184			p.block.Segments = []Segment{tokens}
185			return nil
186		}
187	
188		if ok, name := p.isSnippet(); ok {
189			if p.definedSnippets == nil {
190				p.definedSnippets = map[string][]Token{}
191			}
192			if _, found := p.definedSnippets[name]; found {
193				return p.Errf("redeclaration of previously declared snippet %s", name)
194			}
195			// consume all tokens til matched close brace
196			tokens, err := p.blockTokens(false)
197			if err != nil {
198				return err
199			}
200			// Just as we need to track which file the token comes from, we need to
201			// keep track of which snippet the token comes from. This is helpful
202			// in tracking import cycles across files/snippets by namespacing them.
203			// Without this, we end up with false-positives in cycle-detection.
204			for k, v := range tokens {
205				v.snippetName = name
206				tokens[k] = v
207			}
208			p.definedSnippets[name] = tokens
209			// empty block keys so we don't save this block as a real server.
210			p.block.Keys = nil
211			return nil
212		}
213	
214		return p.blockContents()
215	}
216	
217	func (p *parser) addresses() error {
218		var expectingAnother bool
219	
220		for {
221			value := p.Val()
222			token := p.Token()
223	
224			// Reject request matchers if trying to define them globally
225			if strings.HasPrefix(value, "@") {
226				return p.Errf("request matchers may not be defined globally, they must be in a site block; found %s", value)
227			}
228	
229			// Special case: import directive replaces tokens during parse-time
230			if value == "import" && p.isNewLine() {
231				err := p.doImport(0)
232				if err != nil {
233					return err
234				}
235				continue
236			}
237	
238			// Open brace definitely indicates end of addresses
239			if value == "{" {
240				if expectingAnother {
241					return p.Errf("Expected another address but had '%s' - check for extra comma", value)
242				}
243				// Mark this server block as being defined with braces.
244				// This is used to provide a better error message when
245				// the user may have tried to define two server blocks
246				// without having used braces, which are required in
247				// that case.
248				p.block.HasBraces = true
249				break
250			}
251	
252			// Users commonly forget to place a space between the address and the '{'
253			if strings.HasSuffix(value, "{") {
254				return p.Errf("Site addresses cannot end with a curly brace: '%s' - put a space between the token and the brace", value)
255			}
256	
257			if value != "" { // empty token possible if user typed ""
258				// Trailing comma indicates another address will follow, which
259				// may possibly be on the next line
260				if value[len(value)-1] == ',' {
261					value = value[:len(value)-1]
262					expectingAnother = true
263				} else {
264					expectingAnother = false // but we may still see another one on this line
265				}
266	
267				// If there's a comma here, it's probably because they didn't use a space
268				// between their two domains, e.g. "foo.com,bar.com", which would not be
269				// parsed as two separate site addresses.
270				if strings.Contains(value, ",") {
271					return p.Errf("Site addresses cannot contain a comma ',': '%s' - put a space after the comma to separate site addresses", value)
272				}
273	
274				// After the above, a comma surrounded by spaces would result
275				// in an empty token which we should ignore
276				if value != "" {
277					// Add the token as a site address
278					token.Text = value
279					p.block.Keys = append(p.block.Keys, token)
280				}
281			}
282	
283			// Advance token and possibly break out of loop or return error
284			hasNext := p.Next()
285			if expectingAnother && !hasNext {
286				return p.EOFErr()
287			}
288			if !hasNext {
289				p.eof = true
290				break // EOF
291			}
292			if !expectingAnother && p.isNewLine() {
293				break
294			}
295		}
296	
297		return nil
298	}
299	
300	func (p *parser) blockContents() error {
301		errOpenCurlyBrace := p.openCurlyBrace()
302		if errOpenCurlyBrace != nil {
303			// single-server configs don't need curly braces
304			p.cursor--
305		}
306	
307		err := p.directives()
308		if err != nil {
309			return err
310		}
311	
312		// only look for close curly brace if there was an opening
313		if errOpenCurlyBrace == nil {
314			err = p.closeCurlyBrace()
315			if err != nil {
316				return err
317			}
318		}
319	
320		return nil
321	}
322	
323	// directives parses through all the lines for directives
324	// and it expects the next token to be the first
325	// directive. It goes until EOF or closing curly brace
326	// which ends the server block.
327	func (p *parser) directives() error {
328		for p.Next() {
329			// end of server block
330			if p.Val() == "}" {
331				// p.nesting has already been decremented
332				break
333			}
334	
335			// special case: import directive replaces tokens during parse-time
336			if p.Val() == "import" {
337				err := p.doImport(1)
338				if err != nil {
339					return err
340				}
341				p.cursor-- // cursor is advanced when we continue, so roll back one more
342				continue
343			}
344	
345			// normal case: parse a directive as a new segment
346			// (a "segment" is a line which starts with a directive
347			// and which ends at the end of the line or at the end of
348			// the block that is opened at the end of the line)
349			if err := p.directive(); err != nil {
350				return err
351			}
352		}
353	
354		return nil
355	}
356	
357	// doImport swaps out the import directive and its argument
358	// (a total of 2 tokens) with the tokens in the specified file
359	// or globbing pattern. When the function returns, the cursor
360	// is on the token before where the import directive was. In
361	// other words, call Next() to access the first token that was
362	// imported.
363	func (p *parser) doImport(nesting int) error {
364		// syntax checks
365		if !p.NextArg() {
366			return p.ArgErr()
367		}
368		importPattern := p.Val()
369		if importPattern == "" {
370			return p.Err("Import requires a non-empty filepath")
371		}
372	
373		// grab remaining args as placeholder replacements
374		args := p.RemainingArgs()
375	
376		// set up a replacer for non-variadic args replacement
377		repl := makeArgsReplacer(args)
378	
379		// grab all the tokens (if it exists) from within a block that follows the import
380		var blockTokens []Token
381		for currentNesting := p.Nesting(); p.NextBlock(currentNesting); {
382			blockTokens = append(blockTokens, p.Token())
383		}
384		// initialize with size 1
385		blockMapping := make(map[string][]Token, 1)
386		if len(blockTokens) > 0 {
387			// use such tokens to create a new dispenser, and then use it to parse each block
388			bd := NewDispenser(blockTokens)
389	
390			// one iteration processes one sub-block inside the import
391			for bd.Next() {
392				currentMappingKey := bd.Val()
393	
394				if currentMappingKey == "{" {
395					return p.Err("anonymous blocks are not supported")
396				}
397	
398				// load up all arguments (if there even are any)
399				currentMappingTokens := bd.RemainingArgsAsTokens()
400	
401				// load up the entire block
402				for mappingNesting := bd.Nesting(); bd.NextBlock(mappingNesting); {
403					currentMappingTokens = append(currentMappingTokens, bd.Token())
404				}
405	
406				blockMapping[currentMappingKey] = currentMappingTokens
407			}
408		}
409	
410		// splice out the import directive and its arguments
411		// (2 tokens, plus the length of args)
412		tokensBefore := p.tokens[:p.cursor-1-len(args)-len(blockTokens)]
413		tokensAfter := p.tokens[p.cursor+1:]
414		var importedTokens []Token
415		var nodes []string
416	
417		// first check snippets. That is a simple, non-recursive replacement
418		if p.definedSnippets != nil && p.definedSnippets[importPattern] != nil {
419			importedTokens = p.definedSnippets[importPattern]
420			if len(importedTokens) > 0 {
421				// just grab the first one
422				nodes = append(nodes, p.fileNodeName(importedTokens[0].File, importedTokens[0].snippetName))
423			}
424		} else {
425			// expand file imports (and globs) into tokens; nodes are the
426			// canonical file identities so the import graph tracks the same
427			// real file regardless of how it was addressed
428			fileTokens, fileNodes, err := p.resolveFileImports(importPattern)
429			if err != nil {
430				return err
431			}
432			importedTokens = fileTokens
433			nodes = fileNodes
434		}
435	
436		nodeName := p.graphNodeName()
437		p.importGraph.addNode(nodeName)
438		p.importGraph.addNodes(nodes)
439		if err := p.importGraph.addEdges(nodeName, nodes); err != nil {
440			p.importGraph.removeNodes(nodes)
441			// surface the offending import site along with the cycle chain so
442			// the error is diagnosable even when the loop closes through an
443			// alias that resolves to the current file
444			return p.Errf("%v (while importing %s)", err, importPattern)
445		}
446	
447		// copy the tokens so we don't overwrite p.definedSnippets
448		tokensCopy := make([]Token, 0, len(importedTokens))
449	
450		var (
451			maybeSnippet   bool
452			maybeSnippetId bool
453			index          int
454		)
455	
456		// run the argument replacer on the tokens
457		// golang for range slice return a copy of value
458		// similarly, append also copy value
459		for i, token := range importedTokens {
460			// update the token's imports to refer to import directive filename, line number and snippet name if there is one
461			if token.snippetName != "" {
462				token.imports = append(token.imports, fmt.Sprintf("%s:%d (import %s)", p.File(), p.Line(), token.snippetName))
463			} else {
464				token.imports = append(token.imports, fmt.Sprintf("%s:%d (import)", p.File(), p.Line()))
465			}
466	
467			// naive way of determine snippets, as snippets definition can only follow name + block
468			// format, won't check for nesting correctness or any other error, that's what parser does.
469			if !maybeSnippet && nesting == 0 {
470				// first of the line
471				if i == 0 || isNextOnNewLine(tokensCopy[len(tokensCopy)-1], token) {
472					index = 0
473				} else {
474					index++
475				}
476	
477				if index == 0 && len(token.Text) >= 3 && strings.HasPrefix(token.Text, "(") && strings.HasSuffix(token.Text, ")") {
478					maybeSnippetId = true
479				}
480			}
481	
482			switch token.Text {
483			case "{":
484				nesting++
485				if index == 1 && maybeSnippetId && nesting == 1 {
486					maybeSnippet = true
487					maybeSnippetId = false
488				}
489			case "}":
490				nesting--
491				if nesting == 0 && maybeSnippet {
492					maybeSnippet = false
493				}
494			}
495			// if it is {block}, we substitute with all tokens in the block
496			// if it is {blocks.*}, we substitute with the tokens in the mapping for the *
497			var tokensToAdd []Token
498			foundBlockDirective := false
499			switch {
500			case token.Text == "{block}":
501				foundBlockDirective = true
502				tokensToAdd = blockTokens
503			case strings.HasPrefix(token.Text, "{blocks.") && strings.HasSuffix(token.Text, "}"):
504				foundBlockDirective = true
505				// {blocks.foo.bar} will be extracted to key `foo.bar`
506				blockKey := strings.TrimPrefix(strings.TrimSuffix(token.Text, "}"), "{blocks.")
507				val, ok := blockMapping[blockKey]
508				if ok {
509					tokensToAdd = val
510				}
511			}
512	
513			if foundBlockDirective {
514				if maybeSnippet {
515					tokensCopy = append(tokensCopy, token)
516				} else {
517					tokensCopy = append(tokensCopy, tokensToAdd...)
518				}
519				continue
520			}
521	
522			if maybeSnippet {
523				tokensCopy = append(tokensCopy, token)
524				continue
525			}
526	
527			foundVariadic, startIndex, endIndex := parseVariadic(token, len(args))
528			if foundVariadic {
529				for _, arg := range args[startIndex:endIndex] {
530					token.Text = arg
531					tokensCopy = append(tokensCopy, token)
532				}
533			} else {
534				token.Text = repl.ReplaceKnown(token.Text, "")
535				tokensCopy = append(tokensCopy, token)
536			}
537		}
538	
539		// splice the imported tokens in the place of the import statement
540		// and rewind cursor so Next() will land on first imported token
541		p.tokens = append(tokensBefore, append(tokensCopy, tokensAfter...)...)
542		p.cursor -= len(args) + len(blockTokens) + 1
543	
544		return nil
545	}
