547	// graphNodeName returns the import-graph node for the file currently
548	// being processed. Tokens belonging to a file read from disk carry its
549	// canonical identity in File (set in doSingleImport), so the same real
550	// file reached through an alias or ".." maps to one node. The virtual
551	// root of an inline adaptation ("Caddyfile") keeps its lexical name.
552	// Snippet tokens are namespaced by snippet name so importing a snippet
553	// remains distinct from importing its file.
554	func (p *parser) graphNodeName() string {
555		return p.fileNodeName(p.File(), p.Token().snippetName)
556	}
557	
558	// fileNodeName builds the graph node for a file, optionally namespaced
559	// by snippet name. The file argument is expected to already be the
560	// canonical identity produced when the file was read.
561	func (p *parser) fileNodeName(file, snippet string) string {
562		name := file
563		if snippet != "" {
564			name += fmt.Sprintf(":%s", snippet)
565		}
566		return name
567	}
568	
569	// resolveFileImports expands an import pattern (a concrete path or a
570	// glob) into the imported tokens. It also returns the canonical
571	// identities of the imported files, for import-cycle tracking.
572	//
573	// Canonical identities are symlink-resolved, absolute, cleaned paths, so
574	// the same physical file reached by different spellings (symlink
575	// aliases, ".." segments, or a mix of absolute and relative paths) is
576	// treated as one file. The lexical path is still used to open the file;
577	// once read, its tokens are anchored to the canonical path, so a file
578	// reached through a symlink resolves its own relative imports against
579	// the file that declares them.
580	//
581	// Within a single glob, a file matched more than once (for example both
582	// a real file and a symlink to it) expands only once, in a deterministic
583	// order based on the canonical path. Explicitly repeated imports are
584	// different statements and keep their own semantics.
585	func (p *parser) resolveFileImports(importPattern string) ([]Token, []string, error) {
586		// make path relative to the file of the _token_ being processed rather
587		// than current working directory (issue #867) and then use glob to get
588		// list of matching filenames
589		absFile, err := caddy.FastAbs(p.Dispenser.File())
590		if err != nil {
591			return nil, nil, p.Errf("Failed to get absolute path of file: %s: %v", p.Dispenser.File(), err)
592		}
593	
594		var globPattern string
595		if !filepath.IsAbs(importPattern) {
596			globPattern = filepath.Join(filepath.Dir(absFile), importPattern)
597		} else {
598			globPattern = importPattern
599		}
600		if strings.Count(globPattern, "*") > 1 || strings.Count(globPattern, "?") > 1 ||
601			(strings.Contains(globPattern, "[") && strings.Contains(globPattern, "]")) {
602			// See issue #2096 - a pattern with many glob expansions can hang for too long
603			return nil, nil, p.Errf("Glob pattern may only contain one wildcard (*), but has others: %s", globPattern)
604		}
605		matches, err := filepath.Glob(globPattern)
606		if err != nil {
607			return nil, nil, p.Errf("Failed to use import pattern %s: %v", importPattern, err)
608		}
609		if len(matches) == 0 {
610			if strings.ContainsAny(globPattern, "*?[]") {
611				caddy.Log().Warn("No files matching import glob pattern", zap.String("pattern", importPattern))
612				return nil, nil, nil
613			}
614			return nil, nil, p.Errf("File to import not found: %s", importPattern)
615		}
616	
617		// See issue #5295 - should skip any files that start with a . when iterating over them.
618		sep := string(filepath.Separator)
619		segGlobPattern := strings.Split(globPattern, sep)
620		if strings.HasPrefix(segGlobPattern[len(segGlobPattern)-1], "*") {
621			var tmpMatches []string
622			for _, m := range matches {
623				seg := strings.Split(m, sep)
624				if !strings.HasPrefix(seg[len(seg)-1], ".") {
625					tmpMatches = append(tmpMatches, m)
626				}
627			}
628			matches = tmpMatches
629		}
630	
631		// A single glob statement may address the same real file more than
632		// once (a file and a symlink alias, two aliases, or equivalent
633		// spellings). Resolve each lexical match to its canonical identity,
634		// drop duplicates, and sort by canonical path so the expansion order
635		// is stable and independent of how the pattern was written or the
636		// order the filesystem returned entries in.
637		type resolvedImport struct {
638			lexical string // path used to read the file and anchor its relative imports
639			real    string // canonical identity used for dedup and cycle tracking
640		}
641		resolved := make([]resolvedImport, 0, len(matches))
642		seen := make(map[string]struct{}, len(matches))
643		for _, match := range matches {
644			realPath, err := p.realPath(match)
645			if err != nil {
646				return nil, nil, p.Errf("Could not resolve import %s: %v", match, err)
647			}
648			if _, dup := seen[realPath]; dup {
649				continue
650			}
651			seen[realPath] = struct{}{}
652			resolved = append(resolved, resolvedImport{lexical: match, real: realPath})
653		}
654		slices.SortFunc(resolved, func(a, b resolvedImport) int {
655			return strings.Compare(a.real, b.real)
656		})
657	
658		var importedTokens []Token
659		nodes := make([]string, 0, len(resolved))
660		for _, imp := range resolved {
661			newTokens, err := p.doSingleImport(imp.lexical)
662			if err != nil {
663				return nil, nil, err
664			}
665			importedTokens = append(importedTokens, newTokens...)
666			nodes = append(nodes, imp.real)
667		}
668	
669		return importedTokens, nodes, nil
670	}
671	
672	// realPath returns the canonical identity of a file path: absolute,
673	// cleaned, symlinks resolved, and spelled as the names exist on disk.
674	// It is used to recognize the same physical file across different
675	// spellings. Results are memoized for the duration of a parse so
676	// repeated adaptation over the same file tree is consistent and avoids
677	// redundant filesystem work.
678	//
679	// Case rules are observed from the running filesystem rather than from
680	// the target operating system: a case-insensitive volume (such as a
681	// default APFS or FAT mount on a Unix-like system) folds names that
682	// differ only in case, while a case-sensitive volume does not. See
683	// canonicalCasePath.
684	//
685	// If a path cannot be fully evaluated (for example a dangling symlink),
686	// it falls back to the cleaned absolute path; the subsequent open in
687	// doSingleImport then reports the underlying I/O error using the
688	// existing error paths.
689	func (p *parser) realPath(path string) (string, error) {
690		if p.realPathCache == nil {
691			p.realPathCache = make(map[string]string)
692		}
693		if cached, ok := p.realPathCache[path]; ok {
694			return cached, nil
695		}
696	
697		abs, err := caddy.FastAbs(path)
698		if err != nil {
699			return "", err
700		}
701	
702		// Resolve symlinks to obtain the real file identity. If the path
703		// cannot be fully evaluated (a dangling symlink, a permission error,
704		// ...), fall back to the cleaned absolute path: the subsequent open
705		// in doSingleImport then reports the underlying I/O error using the
706		// existing error paths, so unreadable imports keep their established
707		// error categories.
708		real := abs
709		if resolved, err := filepath.EvalSymlinks(abs); err == nil {
710			real = filepath.Clean(resolved)
711		}
712	
713		// Fold the spelling the way the live filesystem does, so names
714		// differing only in case on a case-insensitive volume map to one
715		// identity (and are left apart on a case-sensitive one).
716		real = p.canonicalCasePath(real)
717	
718		p.realPathCache[path] = real
719		return real, nil
720	}
721	
722	// canonicalCasePath rewrites each component of an absolute, symlink-resolved
723	// path to the spelling it actually has on disk when the containing directory
724	// folds name case.
725	//
726	// Whether two names differing only in case denote the same file is a property
727	// of the filesystem the path is mounted on, not of the operating system: a
728	// case-insensitive APFS, NTFS or FAT volume folds them even on a Unix kernel,
729	// while a case-sensitive volume keeps distinct names. Rather than assume a
730	// rule per GOOS, each component is probed against the live directory: if the
731	// component has no exact on-disk spelling but stat-ing that spelling resolves
732	// to another entry that differs only in case, the volume folds case and the
733	// on-disk spelling is used. On a case-sensitive volume the stat fails (or
734	// names a different file), so the lexical spelling is left untouched. As soon
735	// as a component cannot be inspected, the remaining components keep their
736	// lexical spelling; such paths then fail through the usual import error
737	// paths.
738	func (p *parser) canonicalCasePath(resolved string) string {
739		sep := string(filepath.Separator)
740		vol := filepath.VolumeName(resolved)
741		rest := strings.TrimPrefix(resolved[len(vol):], sep)
742		components := strings.Split(rest, sep)
743	
744		current := vol
745		if current == "" {
746			current = sep
747		} else {
748			current += sep
749		}
750	
751		for i, comp := range components {
752			if comp == "" || comp == "." || comp == ".." {
753				current = filepath.Join(current, comp)
754				continue
755			}
756	
757			entries, err := p.readDirNames(current)
758			if err != nil {
759				// Cannot canonicalize from here on; keep the rest lexical.
760				return filepath.Join(append([]string{current}, components[i:]...)...)
761			}
762	
763			actual := comp
764			if !slices.Contains(entries, comp) {
765				// No entry with the exact spelling. Only fold when the live
766				// filesystem actually resolves this spelling to a sibling
767				// entry that differs in case alone.
768				if lexicalInfo, err := os.Stat(filepath.Join(current, comp)); err == nil {
769					for _, name := range entries {
770						if !strings.EqualFold(name, comp) {
771							continue
772						}
773						realInfo, err := os.Stat(filepath.Join(current, name))
774						if err == nil && os.SameFile(lexicalInfo, realInfo) {
775							actual = name
776						}
777						break
778					}
779				}
780			}
781			current = filepath.Join(current, actual)
782		}
783	
784		return current
785	}
786	
787	// readDirNames returns the entry names of dir, memoized for the duration of
788	// the parse so canonicalizing many paths in the same tree does not re-read
789	// directories.
790	func (p *parser) readDirNames(dir string) ([]string, error) {
791		if p.dirEntriesCache != nil {
792			if names, ok := p.dirEntriesCache[dir]; ok {
793				return names, nil
794			}
795		}
796		entries, err := os.ReadDir(dir)
797		if err != nil {
798			return nil, err
799		}
800		names := make([]string, 0, len(entries))
801		for _, entry := range entries {
802			names = append(names, entry.Name())
803		}
804		if p.dirEntriesCache == nil {
805			p.dirEntriesCache = make(map[string][]string)
806		}
807		p.dirEntriesCache[dir] = names
808		return names, nil
809	}
810	
811	// doSingleImport lexes the individual file at importFile and returns
812	// its tokens or an error, if any.
813	func (p *parser) doSingleImport(importFile string) ([]Token, error) {
814		// Stat before opening: on some platforms opening certain non-regular
815		// files (a FIFO, for example) blocks until another end shows up, so
816		// opening first could hang the adaptation. os.Stat follows symlinks,
817		// matching the previous open-then-fstat behavior for aliases.
818		info, err := os.Stat(importFile)
819		if err != nil {
820			return nil, p.Errf("Could not import %s: %v", importFile, err)
821		}
822		if info.IsDir() {
823			return nil, p.Errf("Could not import %s: is a directory", importFile)
824		}
825		if info.Mode()&os.ModeType != 0 {
826			// a non-regular file (FIFO, socket, device, ...) is not a
827			// readable Caddyfile; reject it with the directory case's
828			// error wrapping and category
829			return nil, p.Errf("Could not import %s: not a regular file", importFile)
830		}
831	
832		file, err := os.Open(importFile)
833		if err != nil {
834			return nil, p.Errf("Could not import %s: %v", importFile, err)
835		}
836		defer file.Close()
837	
838		input, err := io.ReadAll(file)
839		if err != nil {
840			return nil, p.Errf("Could not read imported file %s: %v", importFile, err)
841		}
842	
843		// only warning in case of empty files
844		if len(input) == 0 || len(strings.TrimSpace(string(input))) == 0 {
845			caddy.Log().Warn("Import file is empty", zap.String("file", importFile))
846			return []Token{}, nil
847		}
848	
849		importedTokens, err := allTokens(importFile, input)
850		if err != nil {
851			return nil, p.Errf("Could not read tokens while importing %s: %v", importFile, err)
852		}
853	
854		// Tack the file path onto these tokens so errors show the imported file's name
855		// (we use full, absolute path to avoid bugs: issue #1892). Use the canonical,
856		// symlink-resolved path: relative imports inside an imported file must resolve
857		// relative to the file that actually declares them, even when it was reached
858		// through a symlink alias or a path containing "..".
859		filename, err := p.realPath(importFile)
860		if err != nil {
861			return nil, p.Errf("Failed to get absolute path of file: %s: %v", importFile, err)
862		}
863		for i := range importedTokens {
864			importedTokens[i].File = filename
865		}
866	
867		return importedTokens, nil
868	}
869	
870	// directive collects tokens until the directive's scope
871	// closes (either end of line or end of curly brace block).
872	// It expects the currently-loaded token to be a directive
873	// (or } that ends a server block). The collected tokens
874	// are loaded into the current server block for later use
875	// by directive setup functions.
876	func (p *parser) directive() error {
877		// a segment is a list of tokens associated with this directive
878		var segment Segment
879	
880		// the directive itself is appended as a relevant token
881		segment = append(segment, p.Token())
882	
883		for p.Next() {
884			if p.Val() == "{" {
885				p.nesting++
886				if !p.isNextOnNewLine() && p.Token().wasQuoted == 0 {
887					return p.Err("Unexpected next token after '{' on same line")
888				}
889				if p.isNewLine() {
890					return p.Err("Unexpected '{' on a new line; did you mean to place the '{' on the previous line?")
891				}
892			} else if p.Val() == "{}" {
893				if p.isNextOnNewLine() && p.Token().wasQuoted == 0 {
894					return p.Err("Unexpected '{}' at end of line")
895				}
896			} else if p.isNewLine() && p.nesting == 0 {
897				p.cursor-- // read too far
898				break
899			} else if p.Val() == "}" && p.nesting > 0 {
900				p.nesting--
901			} else if p.Val() == "}" && p.nesting == 0 {
902				return p.Err("Unexpected '}' because no matching opening brace")
903			} else if p.Val() == "import" && p.isNewLine() {
904				if err := p.doImport(1); err != nil {
905					return err
906				}
907				p.cursor-- // cursor is advanced when we continue, so roll back one more
908				continue
909			}
910	
911			segment = append(segment, p.Token())
912		}
913	
914		p.block.Segments = append(p.block.Segments, segment)
915	
916		if p.nesting > 0 {
917			return p.EOFErr()
918		}
919	
920		return nil
921	}
922	
923	// openCurlyBrace expects the current token to be an
924	// opening curly brace. This acts like an assertion
925	// because it returns an error if the token is not
926	// an opening curly brace. It does NOT advance the token.
927	func (p *parser) openCurlyBrace() error {
928		if p.Val() != "{" {
929			if p.valLooksLikeGlobalOptionsAfterImportedSnippets() {
930				return p.Err("global options block must appear before import directives; move the global options block to the top of the Caddyfile")
931			}
932			return p.SyntaxErr("{")
933		}
934		return nil
935	}
936	
937	func (p *parser) valLooksLikeGlobalOptionsAfterImportedSnippets() bool {
938		if p.Val() != "import" || len(p.block.Keys) == 0 {
939			return false
940		}
941	
942		for _, key := range p.block.Keys {
943			if !strings.HasPrefix(key.Text, "(") || !strings.HasSuffix(key.Text, ")") {
944				return false
945			}
946		}
947	
948		return true
949	}
950	
951	// closeCurlyBrace expects the current token to be
952	// a closing curly brace. This acts like an assertion
953	// because it returns an error if the token is not
954	// a closing curly brace. It does NOT advance the token.
955	func (p *parser) closeCurlyBrace() error {
956		if p.Val() != "}" {
957			return p.SyntaxErr("}")
958		}
959		return nil
960	}
961	
962	func (p *parser) isNamedRoute() (bool, string) {
963		keys := p.block.Keys
964		// A named route block is a single key with parens, prefixed with &.
965		if len(keys) == 1 && strings.HasPrefix(keys[0].Text, "&(") && strings.HasSuffix(keys[0].Text, ")") {
966			return true, strings.TrimSuffix(keys[0].Text[2:], ")")
967		}
968		return false, ""
969	}
970	
971	func (p *parser) isSnippet() (bool, string) {
972		keys := p.block.Keys
973		// A snippet block is a single key with parens. Nothing else qualifies.
974		if len(keys) == 1 && strings.HasPrefix(keys[0].Text, "(") && strings.HasSuffix(keys[0].Text, ")") {
975			return true, strings.TrimSuffix(keys[0].Text[1:], ")")
976		}
977		return false, ""
978	}
979	
980	// read and store everything in a block for later replay.
981	func (p *parser) blockTokens(retainCurlies bool) ([]Token, error) {
982		// block must have curlies.
983		err := p.openCurlyBrace()
984		if err != nil {
985			return nil, err
986		}
987		nesting := 1 // count our own nesting
988		tokens := []Token{}
989		if retainCurlies {
990			tokens = append(tokens, p.Token())
991		}
992		for p.Next() {
993			if p.Val() == "}" {
994				nesting--
995				if nesting == 0 {
996					if retainCurlies {
997						tokens = append(tokens, p.Token())
998					}
999					break
1000				}
1001			}
1002			if p.Val() == "{" {
1003				nesting++
1004			}
1005			tokens = append(tokens, p.tokens[p.cursor])
1006		}
1007		// make sure we're matched up
1008		if nesting != 0 {
1009			return nil, p.SyntaxErr("}")
1010		}
1011		return tokens, nil
1012	}
1013	
1014	// ServerBlock associates any number of keys from the
1015	// head of the server block with tokens, which are
1016	// grouped by segments.
1017	type ServerBlock struct {
1018		HasBraces    bool
1019		Keys         []Token
1020		Segments     []Segment
1021		IsNamedRoute bool
1022	}
1023	
1024	func (sb ServerBlock) GetKeysText() []string {
1025		res := make([]string, 0, len(sb.Keys))
1026		for _, k := range sb.Keys {
1027			res = append(res, k.Text)
1028		}
1029		return res
1030	}
1031	
1032	// DispenseDirective returns a dispenser that contains
1033	// all the tokens in the server block.
1034	func (sb ServerBlock) DispenseDirective(dir string) *Dispenser {
1035		var tokens []Token
1036		for _, seg := range sb.Segments {
1037			if len(seg) > 0 && seg[0].Text == dir {
1038				tokens = append(tokens, seg...)
1039			}
1040		}
1041		return NewDispenser(tokens)
1042	}
1043	
1044	// Segment is a list of tokens which begins with a directive
1045	// and ends at the end of the directive (either at the end of
1046	// the line, or at the end of a block it opens).
1047	type Segment []Token
1048	
1049	// Directive returns the directive name for the segment.
1050	// The directive name is the text of the first token.
1051	func (s Segment) Directive() string {
1052		if len(s) > 0 {
1053			return s[0].Text
1054		}
1055		return ""
1056	}
1057	
1058	// spanOpen and spanClose are used to bound spans that
1059	// contain the name of an environment variable.
1060	var (
1061		spanOpen, spanClose    = []byte{'{', '$'}, []byte{'}'}
1062		envVarDefaultDelimiter = ":"
1063	)
1064

