102	// A plain file matched twice within one glob through two aliases still
103	// expands only once.
104	func TestImportGlobDeduplicatesTwoAliases(t *testing.T) {
105		dir := t.TempDir()
106		writeImportFile(t, filepath.Join(dir, "real", "a.conf"), site("host-a"))
107		symlinkOrSkip(t, filepath.Join(dir, "real", "a.conf"), filepath.Join(dir, "one.conf"))
108		symlinkOrSkip(t, filepath.Join(dir, "real", "a.conf"), filepath.Join(dir, "two.conf"))
