111		if err != nil {
112			t.Fatalf("expected no error, got: %v", err)
113		}
114	
115		got := blockKeys(blocks)
116		if len(got) != 1 || got[0] != "host-a" {
117			t.Errorf("expected a single [host-a], got %v", got)
118		}
