121	// Expansion order follows the canonical (real) path, not the order the
122	// filesystem returned matches or the lexical spelling of an alias. Here
123	// the alias sorts first lexically but its target sorts after the other
124	// real file.
125	func TestImportGlobOrderFollowsRealPath(t *testing.T) {
126		dir := t.TempDir()
