186	// A relative import containing ".." still resolves against the declaring
187	// file, including across nested imports.
188	func TestImportRelativeWithDotDot(t *testing.T) {
189		dir := t.TempDir()
190		writeImportFile(t, filepath.Join(dir, "proj", "sub", "b.conf"), site("host-b"))
191		writeImportFile(t, filepath.Join(dir, "proj", "a.conf"), "import sub/../sub/b.conf\n"+site("host-a"))
192	
193		blocks, err := parseInDir(t, dir, "import "+filepath.Join(dir, "proj", "a.conf")+"\n")
194		if err != nil {
195			t.Fatalf("expected no error, got: %v", err)
196		}
197	
198		got := blockKeys(blocks)
199		want := []string{"host-b", "host-a"}
200		if strings.Join(got, ",") != strings.Join(want, ",") {
201			t.Errorf("expected %v, got %v", want, got)
202		}
203	}
