205	// A self-import reached through a symlink alias is a real cycle and must
206	// fail fast with a diagnostic naming the file, not a recursion-depth or
207	// generic I/O error.
208	func TestImportCycleThroughSymlinkAlias(t *testing.T) {
209		dir := t.TempDir()
210		a := filepath.Join(dir, "a.conf")
211		writeImportFile(t, a, "import link.conf\n"+site("host-a"))
212		symlinkOrSkip(t, a, filepath.Join(dir, "link.conf"))
213	
214		_, err := parseInDir(t, dir, "import "+a+"\n")
215		if err == nil {
216			t.Fatal("expected a cycle error, got nil")
217		}
218		msg := err.Error()
219		if !strings.Contains(msg, "cycle") {
220			t.Errorf("expected a cycle diagnostic, got: %v", err)
221		}
222		if !strings.Contains(msg, "a.conf") {
223			t.Errorf("expected the diagnostic to name the offending file a.conf, got: %v", err)
224		}
225		if !strings.Contains(msg, "link.conf") {
226			t.Errorf("expected the diagnostic to name the import statement's target, got: %v", err)
227		}
228	}
229	
230	// A multi-file loop closing through a symlink alias must report the full
231	// chain of files involved.
232	func TestImportCycleChainThroughSymlink(t *testing.T) {
233		dir := t.TempDir()
234		a := filepath.Join(dir, "a.conf")
235		writeImportFile(t, a, "import b.conf\n")
236		writeImportFile(t, filepath.Join(dir, "b.conf"), "import link.conf\n")
237		symlinkOrSkip(t, a, filepath.Join(dir, "link.conf"))
238	
239		_, err := parseInDir(t, dir, "import "+a+"\n")
240		if err == nil {
241			t.Fatal("expected a cycle error, got nil")
242		}
243		msg := err.Error()
244		for _, want := range []string{"a.conf", "b.conf", "link.conf"} {
245			if !strings.Contains(msg, want) {
246				t.Errorf("expected diagnostic to contain %q, got: %v", want, err)
247			}
248		}
249		// the chain closes back to its start
250		chain := strings.SplitN(msg, " (while", 2)[0]
251		if !strings.HasPrefix(chain, "import cycle detected: ") {
252			t.Errorf("expected a cycle-chain prefix, got: %v", err)
253		}
254		if !strings.HasSuffix(chain, "a.conf") {
255			t.Errorf("expected the chain to loop back to a.conf, got: %v", err)
256		}
257	}
258	
259	// A loop formed purely by ".." spellings must be detected even though
260	// the lexical paths differ in writing.
261	func TestImportCycleThroughDotDot(t *testing.T) {
262		dir := t.TempDir()
263		a := filepath.Join(dir, "proj", "a.conf")
264		b := filepath.Join(dir, "proj", "sub", "b.conf")
265		writeImportFile(t, a, "import sub/b.conf\n")
266		writeImportFile(t, b, "import ../a.conf\n")
267	
268		_, err := parseInDir(t, dir, "import "+a+"\n")
269		if err == nil {
270			t.Fatal("expected a cycle error, got nil")
271		}
272		msg := err.Error()
273		if !strings.Contains(msg, "cycle") || !strings.Contains(msg, "a.conf") || !strings.Contains(msg, "b.conf") {
274			t.Errorf("expected a chain naming a.conf and b.conf, got: %v", err)
275		}
276	}
277	
278	// The classic recursive self-import still fails, through the new chained
279	// diagnostic.
280	func TestImportRecursiveCycleChain(t *testing.T) {
281		dir := t.TempDir()
282		a := filepath.Join(dir, "a.conf")
283		writeImportFile(t, a, "import a.conf\n")
284	
285		_, err := parseInDir(t, dir, "import "+a+"\n")
286		if err == nil {
287			t.Fatal("expected a cycle error, got nil")
288		}
289		if !strings.Contains(err.Error(), "cycle") {
290			t.Errorf("expected a cycle diagnostic, got: %v", err)
291		}
292	}
