294	// The same regular file imported at distinct points of a diamond-shaped
295	// graph is not a cycle and must succeed. It expands once per explicit
296	// import statement.
297	func TestImportDiamondSameFileNotCycle(t *testing.T) {
298		dir := t.TempDir()
299		writeImportFile(t, filepath.Join(dir, "d.conf"), site("host-d"))
300		writeImportFile(t, filepath.Join(dir, "b.conf"), "import d.conf\n")
301		writeImportFile(t, filepath.Join(dir, "c.conf"), "import d.conf\n")
302		writeImportFile(t, filepath.Join(dir, "a.conf"), "import b.conf\nimport c.conf\n")
303	
304		blocks, err := parseInDir(t, dir, "import "+filepath.Join(dir, "a.conf")+"\n")
305		if err != nil {
306			t.Fatalf("expected a shared leaf not to be a cycle, got: %v", err)
307		}
308	
309		got := blockKeys(blocks)
310		if len(got) != 2 || got[0] != "host-d" || got[1] != "host-d" {
311			t.Errorf("expected two host-d expansions, got %v", got)
312		}
313	}
