315	// Directories remain an error using the existing category.
316	func TestImportDirectoryStillErrors(t *testing.T) {
317		dir := t.TempDir()
318		sub := filepath.Join(dir, "subdir")
319		if err := os.Mkdir(sub, 0o755); err != nil {
320			t.Fatal(err)
321		}
322		_, err := parseInDir(t, dir, "import "+sub+"\n")
323		if err == nil {
324			t.Fatal("expected an error importing a directory, got nil")
325		}
326		if !strings.Contains(err.Error(), "is a directory") {
327			t.Errorf("expected a directory error category, got: %v", err)
