331	// A glob matching nothing is still a non-error; an explicit missing file
332	// is still an error.
333	func TestImportNoMatchCategories(t *testing.T) {
334		dir := t.TempDir()
335		if _, err := parseInDir(t, dir, "import "+filepath.Join(dir, "nope", "*.conf")+"\n"); err != nil {
336			t.Errorf("expected a non-matching glob to be a non-error, got: %v", err)
337		}
338		if _, err := parseInDir(t, dir, "import "+filepath.Join(dir, "nope", "file.conf")+"\n"); err == nil {
339			t.Error("expected a missing explicit file to be an error, got nil")
