342	
343	// Repeatedly adapting the same file tree yields identical expansion
344	// order; a cycle yields the identical error chain.
345	func TestImportDeterministicAcrossRuns(t *testing.T) {
346		dir := t.TempDir()
347		writeImportFile(t, filepath.Join(dir, "a.conf"), site("host-a"))
348		writeImportFile(t, filepath.Join(dir, "m.conf"), site("host-m"))
349		symlinkOrSkip(t, filepath.Join(dir, "a.conf"), filepath.Join(dir, "z-alias.conf"))
350		root := filepath.Join(dir, "Caddyfile")
351		body := []byte("import " + filepath.Join(dir, "*") + "\n")
352	
353		var first []string
354		for run := 0; run < 3; run++ {
355			blocks, err := Parse(root, body)
356			if err != nil {
357				t.Fatalf("run %d: expected no error, got: %v", run, err)
358			}
359			keys := blockKeys(blocks)
360			if first == nil {
361				first = keys
362				continue
363			}
364			if strings.Join(keys, ",") != strings.Join(first, ",") {
365				t.Errorf("run %d: expected %v, got %v", run, first, keys)
366			}
367		}
368	
369		// error chain stability
370		cyc := filepath.Join(dir, "cyc.conf")
371		writeImportFile(t, cyc, "import link2.conf\n")
372		symlinkOrSkip(t, cyc, filepath.Join(dir, "link2.conf"))
373		cycleBody := []byte("import " + cyc + "\n")
374		var firstErr string
375		for run := 0; run < 3; run++ {
376			_, err := Parse(root, cycleBody)
377			if err == nil {
378				t.Fatalf("run %d: expected a cycle error, got nil", run)
379			}
380			if firstErr == "" {
381				firstErr = err.Error()
382				continue
383			}
384			if err.Error() != firstErr {
385				t.Errorf("run %d: expected identical error\nwant: %s\ngot:  %s", run, firstErr, err.Error())
386			}
387		}
388	}
