390	// Exercise the public Adapter.Adapt entry point: a glob that hits the
391	// same real file through an alias expands it once and succeeds, while a
392	// cycle means the whole adaptation fails (the caller never receives a
393	// partially expanded successful result).
394	func TestAdapterImportResolution(t *testing.T) {
395		dir := t.TempDir()
396		root := filepath.Join(dir, "Caddyfile")
397		writeImportFile(t, filepath.Join(dir, "a.conf"), site("host-a"))
398		writeImportFile(t, filepath.Join(dir, "m.conf"), site("host-m"))
399		symlinkOrSkip(t, filepath.Join(dir, "a.conf"), filepath.Join(dir, "z-alias.conf"))
400	
401		var captured []ServerBlock
402		adapter := Adapter{ServerType: captureServerType{blocks: &captured}}
403	
404		// success: alias + real file collapsed, order follows real paths
405		out, _, err := adapter.Adapt([]byte("import "+filepath.Join(dir, "*")+"\n"),
406			map[string]any{"filename": root})
407		if err != nil {
408			t.Fatalf("expected successful adaptation, got: %v", err)
409		}
410		if len(out) == 0 {
411			t.Error("expected non-empty JSON output, got empty")
412		}
413		if got := blockKeys(captured); strings.Join(got, ",") != "host-a,host-m" {
414			t.Errorf("expected hosts [host-a host-m], got %v", got)
415		}
416	
417		// failure: any imported file triggering a cycle fails the whole adapt
418		cyc := filepath.Join(dir, "cyc.conf")
419		writeImportFile(t, cyc, "import alias2.conf\n")
420		symlinkOrSkip(t, cyc, filepath.Join(dir, "alias2.conf"))
421		captured = nil
422		out, _, err = adapter.Adapt([]byte("import "+cyc+"\n"),
423			map[string]any{"filename": root})
424		if err == nil {
425			t.Fatal("expected the whole adaptation to fail on a cycle, got nil")
426		}
427		if out != nil {
428			t.Errorf("expected no partial result on failure (got %d bytes)", len(out))
429		}
430		if captured != nil {
431			t.Errorf("expected Setup not to run on a failed expansion (partial result)")
432		}
433		if !strings.Contains(err.Error(), "cycle") {
434			t.Errorf("expected a cycle diagnostic, got: %v", err)
435		}
436	}
437	
438	// A dangling symlink keeps the existing "not found / could not import"
439	// error category rather than surfacing a path-resolution error.
440	func TestAdapterDanglingSymlinkCategory(t *testing.T) {
441		dir := t.TempDir()
442		root := filepath.Join(dir, "Caddyfile")
443		symlinkOrSkip(t, filepath.Join("does-not-exist"), filepath.Join(dir, "dangling.conf"))
444	
445		var captured []ServerBlock
446		adapter := Adapter{ServerType: captureServerType{blocks: &captured}}
447		_, _, err := adapter.Adapt([]byte("import "+filepath.Join(dir, "dangling.conf")+"\n"),
448			map[string]any{"filename": root})
449		if err == nil {
450			t.Fatal("expected an error for a dangling symlink, got nil")
451		}
452		if strings.Contains(err.Error(), "Could not resolve import") {
453			t.Errorf("dangling symlink should keep existing I/O error category, got: %v", err)
454		}
455	}
