457	// fsCaseInsensitive reports whether dir folds file-name case, observed from
458	// the live filesystem rather than from the target operating system. A
459	// default APFS or NTFS/FAT volume folds case even when the kernel is Unix-like.
460	func fsCaseInsensitive(t *testing.T, dir string) bool {
461		t.Helper()
462		probeName := ".case_probe_abc"
463		probe := filepath.Join(dir, probeName)
464		writeImportFile(t, probe, "")
465		info, err := os.Stat(probe)
466		if err != nil {
467			t.Skipf("cannot probe filesystem case rules: %v", err)
468		}
469		flipped, err := os.Stat(filepath.Join(dir, strings.ToUpper(probeName)))
470		if err != nil {
471			return false
472		}
473		return os.SameFile(info, flipped)
474	}
475	
476	// On a case-insensitive volume, aliases differing only in case (here a symlink
477	// whose target is spelled with different case) still denote the same real
478	// file: a single glob must expand it once and must not depend on a fixed
479	// per-OS folding rule.
480	func TestImportGlobDeduplicatesCaseOnlyAlias(t *testing.T) {
481		dir := t.TempDir()
482		if !fsCaseInsensitive(t, dir) {
483			t.Skip("requires a case-insensitive filesystem")
484		}
485		writeImportFile(t, filepath.Join(dir, "real", "a.conf"), site("host-a"))
486		writeImportFile(t, filepath.Join(dir, "m.conf"), site("host-m"))
487		// the target is spelled in a case that does not exist on disk
488		symlinkOrSkip(t, filepath.Join(dir, "REAL", "A.CONF"), filepath.Join(dir, "z-link.conf"))
489	
490		blocks, err := parseInDir(t, dir, "import "+filepath.Join(dir, "*.conf")+"\n")
491		if err != nil {
492			t.Fatalf("expected no error, got: %v", err)
493		}
494		got := blockKeys(blocks)
495		// the alias canonicalizes to real/a.conf, which sorts after m.conf;
496		// the important assertion is that the alias adds no extra expansion
497		want := []string{"host-m", "host-a"}
498		if strings.Join(got, ",") != strings.Join(want, ",") {
499			t.Errorf("expected %v (case alias collapsed, canonical order), got %v", want, got)
500		}
501	}
502	
503	// A cycle closed through a case-only alias on a case-insensitive volume must
504	// be detected and report the same chain on immediate retries.
505	func TestImportCycleThroughCaseOnlyAlias(t *testing.T) {
506		dir := t.TempDir()
507		if !fsCaseInsensitive(t, dir) {
508			t.Skip("requires a case-insensitive filesystem")
509		}
510		a := filepath.Join(dir, "a.conf")
511		writeImportFile(t, a, "import link.conf\n"+site("host-a"))
512		// the alias points at the same file using a different-case spelling
513		symlinkOrSkip(t, filepath.Join(dir, "A.CONF"), filepath.Join(dir, "link.conf"))
514	
515		body := []byte("import " + a + "\n")
516		var firstErr string
517		for run := 0; run < 2; run++ {
518			_, err := Parse(filepath.Join(dir, "Caddyfile"), body)
519			if err == nil {
520				t.Fatalf("run %d: expected a cycle error, got nil", run)
521			}
522			if run == 0 {
523				firstErr = err.Error()
524				continue
525			}
526			if err.Error() != firstErr {
527				t.Errorf("expected identical error chain on retry\nwant: %s\ngot:  %s", firstErr, err.Error())
528			}
529		}
530		if !strings.Contains(firstErr, "cycle") ||
531			!strings.Contains(firstErr, "a.conf") ||
532			!strings.Contains(firstErr, "link.conf") {
533			t.Errorf("expected a cycle chain naming a.conf and the link, got: %s", firstErr)
534		}
535	}
536	
537	// On a case-sensitive volume, two files whose names differ only in case are
538	// genuinely different files and must both expand; case folding must never be
539	// forced by the implementation.
540	func TestImportCaseDistinctOnCaseSensitiveFS(t *testing.T) {
541		dir := t.TempDir()
542		if fsCaseInsensitive(t, dir) {
543			t.Skip("requires a case-sensitive filesystem")
544		}
545		writeImportFile(t, filepath.Join(dir, "CASE.conf"), site("host-upper"))
546		writeImportFile(t, filepath.Join(dir, "case.conf"), site("host-lower"))
547	
548		blocks, err := parseInDir(t, dir, "import "+filepath.Join(dir, "*.conf")+"\n")
549		if err != nil {
550			t.Fatalf("expected no error, got: %v", err)
551		}
552		got := blockKeys(blocks)
553		if len(got) != 2 {
554			t.Fatalf("expected both case-distinct files to expand, got %v", got)
555		}
556		upper := strings.Join(got, ",")
557		if upper != "host-upper,host-lower" && upper != "host-lower,host-upper" {
558			t.Errorf("expected both hosts in a stable order, got %v", got)
559		}
560	}
561	
562	// A failed adaptation leaves no state that changes later adaptations:
563	// failing, then succeeding, then failing again through the same Adapter
564	// yields the same error category and chain both times.
565	func TestAdapterFailureIsStateless(t *testing.T) {
566		dir := t.TempDir()
567		root := filepath.Join(dir, "Caddyfile")
568		writeImportFile(t, filepath.Join(dir, "a.conf"), site("host-a"))
569		writeImportFile(t, filepath.Join(dir, "cyc.conf"), "import cyc-link.conf\n")
570		symlinkOrSkip(t, filepath.Join(dir, "cyc.conf"), filepath.Join(dir, "cyc-link.conf"))
571	
572		var captured []ServerBlock
573		adapter := Adapter{ServerType: captureServerType{blocks: &captured}}
574		failBody := []byte("import " + filepath.Join(dir, "cyc.conf") + "\n")
575		goodBody := []byte("import " + filepath.Join(dir, "a.conf") + "\n")
576	
577		out, _, err := adapter.Adapt(failBody, map[string]any{"filename": root})
578		if err == nil {
579			t.Fatal("expected the first adaptation to fail, got nil")
580		}
581		if out != nil {
582			t.Errorf("expected no partial output on failure, got %d bytes", len(out))
583		}
584		if captured != nil {
585			t.Error("expected Setup not to run on a failed adaptation")
586		}
587		firstErr := err.Error()
588	
589		if out, _, err := adapter.Adapt(goodBody, map[string]any{"filename": root}); err != nil {
590			t.Fatalf("expected a later adaptation to succeed, got: %v", err)
591		} else if len(out) == 0 {
592			t.Error("expected non-empty output from the successful adaptation")
593		}
594		if got := blockKeys(captured); len(got) != 1 || got[0] != "host-a" {
595			t.Errorf("expected [host-a] after recovery, got %v", got)
596		}
597	
598		captured = nil
599		out, _, err = adapter.Adapt(failBody, map[string]any{"filename": root})
600		if err == nil {
601			t.Fatal("expected the repeated failure to fail again, got nil")
602		}
603		if out != nil {
604			t.Errorf("expected no partial output on the repeated failure, got %d bytes", len(out))
605		}
606		if captured != nil {
607			t.Error("expected Setup not to run on the repeated failure")
608		}
609		if err.Error() != firstErr {
610			t.Errorf("expected the identical error chain after success\nwant: %s\ngot:  %s", firstErr, err.Error())
611		}
612	}
